import * as pdfjsLib from 'pdfjs-dist';

// Set the workerSrc globally to avoid issues with the PDF.js worker
pdfjsLib.GlobalWorkerOptions.workerSrc = `//cdnjs.cloudflare.com/ajax/libs/pdf.js/${pdfjsLib.version}/pdf.worker.min.js`;

const parsePDF = async (file) => {
  const reader = new FileReader();
  reader.readAsArrayBuffer(file);

  return new Promise((resolve, reject) => {
    reader.onload = async function () {
      try {
        const typedArray = new Uint8Array(reader.result);
        const pdf = await pdfjsLib.getDocument(typedArray).promise;

        if (!pdf || !pdf.numPages) {
          reject(new Error('Failed to load PDF document or no pages found.'));
          return;
        }

        let parsedText = '';

        // Loop through all the pages
        for (let i = 1; i <= pdf.numPages; i++) {  // Start from page 1
          const page = await pdf.getPage(i);
          const textContent = await page.getTextContent();

          // Extract text from each page
          const pageText = textContent.items.map((item) => item.str).join(' ');
          parsedText += pageText + '\n';
        }

        // Filter the parsed text into sections
        const filteredData = filterResume(parsedText);

        resolve(filteredData);
      } catch (error) {
        reject(error); // Catch any errors during parsing
      }
    };

    reader.onerror = function (error) {
      reject(error);
    };
  });
};

// Function to filter the resume into sections
const filterResume = (text) => {
  // Regular expressions to find sections
  const contactInfoRegex = /^(.*?)(\n|$)/i;
  const educationRegex = /education(.*?)(experience|projects|skills|$)/is;
  const experienceRegex = /experience(.*?)(projects|skills|$)/is;
  const projectsRegex = /projects(.*?)(skills|$)/is;
  const skillsRegex = /skills(.*?)(\n|$)/is;

  // Extracting the sections using regex
  const contactInfo = text.match(contactInfoRegex)?.[0]?.trim() || '';
  const education = text.match(educationRegex)?.[0]?.trim() || '';
  const experience = text.match(experienceRegex)?.[0]?.trim() || '';
  const projects = text.match(projectsRegex)?.[0]?.trim() || '';
  const skills = text.match(skillsRegex)?.[0]?.trim() || '';

  // Organizing data into an object
  const filteredData = {
    contactInfo,
    education,
    experience,
    projects,
    skills
  };

  return filteredData;
};

export { parsePDF };
